class _PersonalAgentOperationTerminal(RuntimeError):
    def __init__(
        self,
        state: OperationState,
        terminal_code: str | None,
    ) -> None:
        self.state = state
        self.terminal_code = terminal_code
        super().__init__(terminal_code or state.value)


