def _unbind_orchestrator_process_consumers(orchestrator) -> None:
    from orchestrator.offline_grant import unbind_offline_grant_store
    from orchestrator.web_auth import (
        unbind_credential_manager,
        unbind_session_store,
    )

    errors: list[BaseException] = []
    boundary = getattr(orchestrator, "human_request_boundary", None)
    if boundary is not None:
        try:
            boundary.close()
        except BaseException as exc:
            errors.append(exc)
    for callback, attribute in (
        (unbind_offline_grant_store, "offline_grants"),
        (unbind_session_store, "web_sessions"),
        (unbind_credential_manager, "credential_manager"),
    ):
        if not hasattr(orchestrator, attribute):
            continue
        try:
            callback(getattr(orchestrator, attribute))
        except BaseException as exc:
            errors.append(exc)
    if len(errors) == 1:
        raise errors[0]
    if errors:
        raise BaseExceptionGroup(
            "orchestrator process consumer unbind failed",
            errors,
        )


def _transactional_runtime_construction(initializer):
    @wraps(initializer)
    def guarded(self, *args, **kwargs):
        try:
            return initializer(self, *args, **kwargs)
        except BaseException as construction_error:
            cleanup_errors: list[BaseException] = []
            try:
                _unbind_orchestrator_process_consumers(self)
            except BaseException as exc:
                cleanup_errors.append(exc)
            runtime_composition = getattr(self, "runtime_composition", None)
            if runtime_composition is not None:
                try:
                    runtime_composition.abort()
                except BaseException as exc:
                    cleanup_errors.append(exc)
            global _ORCH_INSTANCE
            if _ORCH_INSTANCE is self:
                _ORCH_INSTANCE = None
            if cleanup_errors:
                raise BaseExceptionGroup(
                    "orchestrator construction and rollback both failed",
                    [construction_error, *cleanup_errors],
                ) from construction_error
            raise

    return guarded



def _designer_device(rote, websocket) -> Optional[Dict[str, Any]]:
    try:
        if websocket is None or rote is None:
            return None
        prof = rote.get_profile(websocket)
        if prof is None:
            return None
        dt = prof.device_type.value if prof.device_type else "browser"
        return {
            "device_type": dt,
            "is_small": dt in ("mobile", "watch"),
            "is_voice": dt == "voice",
            "max_grid_columns": int(prof.max_grid_columns),
        }
    except Exception:
        logger.debug("designer device profile unavailable", exc_info=True)
        return None



_PLACEHOLDER_CHAT_TITLES = frozenset({"new chat", "untitled chat", "untitled", "chat"})

_TITLE_MAX_WORDS = 4
_TITLE_MAX_CHARS = 48


def _chat_needs_a_name(chat_data) -> bool:
    if not isinstance(chat_data, dict):
        return False
    title = str(chat_data.get("title") or "").strip()
    return not title or title.lower() in _PLACEHOLDER_CHAT_TITLES


def _title_from(text) -> str:
    if not isinstance(text, str):
        return ""
    line = text.strip().splitlines()[0] if text.strip() else ""
    line = line.strip().strip('"').strip("'").strip()
    for label in ("chat title:", "title:"):
        if line.lower().startswith(label):
            line = line[len(label):].strip().strip('"').strip("'").strip()
            break
    line = line.rstrip(".!,;:").strip()
    if not line:
        return ""
    words = line.split()
    if len(words) > _TITLE_MAX_WORDS:
        words = words[:_TITLE_MAX_WORDS]
    title = " ".join(words)[:_TITLE_MAX_CHARS].strip()
    return "" if title.lower() in _PLACEHOLDER_CHAT_TITLES else title


